// Shared handling for API errors, navigation, forms, and accessible dialogs.
window.addEventListener('unhandledrejection',e=>{e.preventDefault();toast(e.reason?.message||'Something went wrong. Please try again.')});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#reset-password')){resetPasswordScreen(new URLSearchParams(location.hash.split('?')[1]||'').get('token')||'');return}if(state.user){const view=location.hash.slice(1);if(view&&view!==state.view)go(view)}else if(location.hash.startsWith('#login')||location.hash.startsWith('#register'))authScreen()});
document.addEventListener('keydown',e=>{const modals=$$('.modal'),top=modals.at(-1);if(!top)return;if(e.key==='Escape')top.remove();if(e.key==='Tab'){const controls=$$('button,a,input,select,textarea,[tabindex="0"]',top).filter(x=>!x.disabled&&x.offsetParent!==null);if(!controls.length)return;const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
new MutationObserver(records=>{for(const r of records)for(const n of r.addedNodes)if(n.nodeType===1&&n.classList?.contains('modal')){const dialog=n.firstElementChild;dialog?.setAttribute('role','dialog');dialog?.setAttribute('aria-modal','true');if(!dialog?.getAttribute('aria-label'))dialog?.setAttribute('aria-label',$('h2',dialog)?.textContent||'HireMe dialog');enhanceForms(n);setTimeout(()=>n.querySelector('input,button,select')?.focus(),0)}}).observe(document.body,{childList:true});
document.addEventListener('input',e=>{if(e.target.classList.contains('prefWeight'))updateWeightTotal()});
document.addEventListener('change',e=>{if(['applicantRoleFilter','applicantStatusFilter'].includes(e.target.id)){$$('#applicantList article').forEach(row=>{row.hidden=Boolean(($('#applicantRoleFilter').value&&row.dataset.role!==$('#applicantRoleFilter').value)||($('#applicantStatusFilter').value&&row.dataset.status!==$('#applicantStatusFilter').value))})}});
function ensureForgotLink(){const form=$('#authForm');if(!form||$('#forgotPassword'))return;const button=document.createElement('button');button.type='button';button.id='forgotPassword';button.className='text-link mt-4';button.textContent='Forgot password?';button.onclick=forgotPasswordScreen;form.insertAdjacentElement('afterend',button)}
new MutationObserver(ensureForgotLink).observe(document.body,{childList:true,subtree:true});
setInterval(ensureForgotLink,250);
document.addEventListener('submit',async e=>{const form=e.target;if(form.id==='browseSearch'){e.preventDefault();const f=new FormData(form);browseQuery=f.get('query');browseLocation=f.get('location');browseEligible=f.get('eligible')==='yes';render()}if(['messageForm','passwordForm'].includes(form.id)){e.preventDefault();const button=$('button',form);button.disabled=true;try{await api(form.id==='messageForm'?'/api/messages':'/api/settings/password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});toast(form.id==='messageForm'?'Message sent':'Password updated');form.reset();if(form.id==='messageForm')render()}catch(error){toast(error.message)}finally{button.disabled=false}}});
render();
